using System; using System.Configuration; using System.Data; using System.Data.SqlClient; using System.Web.UI;
namespace WAPP_Assignment_Module { public partial class AssessmentDashboardWidget : UserControl { private readonly string cs=ConfigurationManager.ConnectionStrings["DefaultConnection"].ConnectionString; protected void Page_Load(object sender,EventArgs e){ if(!IsPostBack)LoadRecent(); } private void LoadRecent(){try{string u=Context.User.Identity.IsAuthenticated?Context.User.Identity.Name:"Guest";using(SqlConnection con=new SqlConnection(cs)){string q=@"SELECT TOP 5 a.Title,aa.Score,aa.IsPassed,aa.AttemptDate FROM AssessmentAttempts aa INNER JOIN Assessments a ON aa.AssessmentId=a.AssessmentId WHERE aa.TraineeUserName=@u ORDER BY aa.AttemptDate DESC";using(SqlDataAdapter da=new SqlDataAdapter(q,con)){da.SelectCommand.Parameters.AddWithValue("@u",u);DataTable dt=new DataTable();da.Fill(dt);if(dt.Rows.Count==0)lblMessage.Text="No assessment attempts yet.";gvRecentAttempts.DataSource=dt;gvRecentAttempts.DataBind();}}}catch(Exception ex){lblMessage.Text="Error loading assessment dashboard: "+ex.Message;}} } }
